#[tokio::test]
async fn duplicate_and_denied_decisions_never_authorize_execution() {
    let store = TaskStore::new(":memory:").unwrap();
    let pending = parked(&store).await;
    let denied = store
        .claim_tool_approval(pending.task_id, pending.request_id, false)
        .await
        .unwrap();
    assert!(
        denied.is_some(),
        "first denial consumes the pending request"
    );
    assert!(!store.begin_approved_execution(&pending).await.unwrap());
    for approve in [true, false] {
        assert!(store
            .claim_tool_approval(pending.task_id, pending.request_id, approve)
            .await
            .unwrap()
            .is_none());
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn competing_approvals_and_denials_have_exactly_one_winner() {
    for decisions in [(true, true), (true, false), (false, false)] {
        let store = Arc::new(TaskStore::new(":memory:").unwrap());
        let pending = parked(&store).await;
        let barrier = Arc::new(tokio::sync::Barrier::new(3));
        let mut jobs = Vec::new();
        for approve in [decisions.0, decisions.1] {
            let store = store.clone();
            let barrier = barrier.clone();
            let pending = pending.clone();
            jobs.push(tokio::spawn(async move {
                barrier.wait().await;
                let result = store
                    .claim_tool_approval(pending.task_id, pending.request_id, approve)
                    .await
                    .unwrap();
                (approve, result)
            }));
        }
        barrier.wait().await;
        let first = jobs.remove(0).await.unwrap();
        let second = jobs.remove(0).await.unwrap();
        let winners: Vec<_> = [first, second]
            .into_iter()
            .filter(|(_, result)| result.is_some())
            .collect();
        assert_eq!(
            winners.len(),
            1,
            "the database must atomically consume the request"
        );
        assert_eq!(
            store.begin_approved_execution(&pending).await.unwrap(),
            winners[0].0,
            "execution authority follows the unique winning decision"
        );
        assert!(!store.begin_approved_execution(&pending).await.unwrap());
    }
}

#[tokio::test]
async fn cancellation_and_pause_invalidate_pending_and_claimed_requests() {
    for status in [TaskStatus::Cancelled, TaskStatus::Paused] {
        for after_claim in [false, true] {
            let store = TaskStore::new(":memory:").unwrap();
            let pending = parked(&store).await;
            if after_claim {
                assert!(store
                    .claim_tool_approval(pending.task_id, pending.request_id, true)
                    .await
                    .unwrap()
                    .is_some());
            }
            // This fixes the ordering deterministically: cancellation is fully
            // committed before the execution boundary is attempted.
            store.set_status(pending.task_id, status).await.unwrap();
            assert!(!store.begin_approved_execution(&pending).await.unwrap());
            assert!(store
                .claim_tool_approval(pending.task_id, pending.request_id, true)
                .await
                .unwrap()
                .is_none());
            let task = store.get(pending.task_id).await.unwrap().unwrap();
            assert_eq!(task.status, status);
            assert!(task.pending_tool_approval.is_none());
        }
    }
}

#[tokio::test]
async fn repeated_provider_call_id_does_not_inherit_previous_approval() {
    let store = TaskStore::new(":memory:").unwrap();
    let first = parked(&store).await;
    assert!(store
        .claim_tool_approval(first.task_id, first.request_id, true)
        .await
        .unwrap()
        .is_some());
    assert!(store.begin_approved_execution(&first).await.unwrap());
    store
        .complete_tool_approval(first.request_id)
        .await
        .unwrap();
    let second = store
        .park_tool_approval(first.task_id, Uuid::new_v4(), &call(), server())
        .await
        .unwrap()
        .unwrap();
    assert_eq!(first.tool_call_id, second.tool_call_id);
    assert_ne!(first.request_id, second.request_id);
    assert_ne!(first.execution_id, second.execution_id);
    assert!(!store.begin_approved_execution(&first).await.unwrap());
    assert!(!store.begin_approved_execution(&second).await.unwrap());
    assert!(store
        .claim_tool_approval(second.task_id, first.request_id, true)
        .await
        .unwrap()
        .is_none());
}

struct DatabaseFile(std::path::PathBuf);

impl DatabaseFile {
    fn new() -> Self {
        Self(std::env::temp_dir().join(format!("kaic-p0-approval-{}.db", Uuid::new_v4())))
    }
}

impl Drop for DatabaseFile {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.0);
    }
}

#[tokio::test]
async fn restart_preserves_pending_identity_and_execution_cannot_replay() {
    for restart_after_claim in [false, true] {
        let db = DatabaseFile::new();
        let pending = {
            let store = TaskStore::new(&db.0).unwrap();
            let pending = parked(&store).await;
            if restart_after_claim {
                assert!(store
                    .claim_tool_approval(pending.task_id, pending.request_id, true)
                    .await
                    .unwrap()
                    .is_some());
            }
            pending
        };
        let store = TaskStore::new(&db.0).unwrap();
        if !restart_after_claim {
            assert_eq!(
                store
                    .get(pending.task_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .pending_tool_approval,
                Some(pending.clone())
            );
            assert_eq!(
                store
                    .claim_tool_approval(pending.task_id, pending.request_id, true)
                    .await
                    .unwrap(),
                Some(pending.clone())
            );
        }
        // Deliberately retain the in-process snapshot across reopening to stress
        // the SQL fence. Production HTTP cannot reacquire a claimed snapshot:
        // duplicate decisions and ordinary continue are rejected separately.
        assert!(store.begin_approved_execution(&pending).await.unwrap());
        drop(store);
        let store = TaskStore::new(&db.0).unwrap();
        assert!(!store.begin_approved_execution(&pending).await.unwrap());
        assert!(store
            .claim_tool_approval(pending.task_id, pending.request_id, true)
            .await
            .unwrap()
            .is_none());
    }
}

#[test]
fn multiple_tool_calls_are_rejected_before_any_call_is_selected() {
    let first = call();
    let mut second = call();
    second.id = "last-call".to_owned();
    second.name = "different_tool".to_owned();
    second.arguments = "{\"dangerous\":true}".to_owned();
    assert!(validate_tool_calls(&[]).is_err());
    assert!(validate_tool_calls(&[first.clone()]).is_ok());
    assert!(validate_tool_calls(&[first.clone(), second.clone()]).is_err());
    assert!(validate_tool_calls(&[second, first]).is_err());
}

#[tokio::test]
async fn resuming_cancelled_task_does_not_resurrect_old_approval() {
    let store = TaskStore::new(":memory:").unwrap();
    let first = parked(&store).await;
    store
        .set_status(first.task_id, TaskStatus::Cancelled)
        .await
        .unwrap();
    store
        .set_status(first.task_id, TaskStatus::Running)
        .await
        .unwrap();
    let second = store
        .park_tool_approval(first.task_id, Uuid::new_v4(), &call(), server())
        .await
        .unwrap()
        .unwrap();
    assert_ne!(first.request_id, second.request_id);
    assert!(store
        .claim_tool_approval(first.task_id, first.request_id, true)
        .await
        .unwrap()
        .is_none());
    assert!(!store.begin_approved_execution(&first).await.unwrap());
    assert_eq!(
        store
            .get(first.task_id)
            .await
            .unwrap()
            .unwrap()
            .pending_tool_approval,
        Some(second)
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn concurrent_execution_claims_have_one_external_effect_boundary() {
    let store = Arc::new(TaskStore::new(":memory:").unwrap());
    let pending = parked(&store).await;
    store
        .claim_tool_approval(pending.task_id, pending.request_id, true)
        .await
        .unwrap()
        .unwrap();
    let barrier = Arc::new(tokio::sync::Barrier::new(3));
    let mut jobs = Vec::new();
    for _ in 0..2 {
        let store = store.clone();
        let pending = pending.clone();
        let barrier = barrier.clone();
        jobs.push(tokio::spawn(async move {
            barrier.wait().await;
            store.begin_approved_execution(&pending).await.unwrap()
        }));
    }
    barrier.wait().await;
    let first = jobs.remove(0).await.unwrap();
    let second = jobs.remove(0).await.unwrap();
    assert_eq!(usize::from(first) + usize::from(second), 1);
}

#[tokio::test]
async fn changed_current_server_is_rejected_without_consuming_approval() {
    let store = TaskStore::new(":memory:").unwrap();
    let pending = parked(&store).await;
    store
        .claim_tool_approval(pending.task_id, pending.request_id, true)
        .await
        .unwrap()
        .unwrap();
    assert!(validate_approval_target(&pending, pending.task_id, &server()).is_ok());
    assert!(validate_approval_target(&pending, Uuid::new_v4(), &server()).is_err());
    let mut changed_servers = Vec::new();
    let mut changed = server();
    changed.command.push_str("-replacement");
    changed_servers.push(changed);
    let mut changed = server();
    changed.args.push("--changed-config".to_owned());
    changed_servers.push(changed);
    let mut changed = server();
    changed.peer_name.push_str("-different-peer");
    changed_servers.push(changed);
    for changed in changed_servers {
        assert!(validate_approval_target(&pending, pending.task_id, &changed).is_err());
    }
    // Validation itself neither burns nor expands the immutable permission.
    assert!(store.begin_approved_execution(&pending).await.unwrap());
}

