#[tokio::test]
async fn actual_agent_loop_rejects_batch_before_history_or_pending_side_effects() {
    let dir = FixtureDirectory::new();
    let resource_path = dir.0.join("resources.yaml");
    std::fs::write(
        &resource_path,
        "Fake:\n  vram_mb: 1000\n  load_seconds: 1\n",
    )
    .unwrap();
    let capabilities_path = dir.0.join("capabilities.yaml");
    std::fs::write(&capabilities_path, "Simple:\n  primary: Fake\n").unwrap();
    let scheduler = Scheduler::new(
        Arc::new(
            crate::capability_registry::CapabilityRegistry::from_file(&capabilities_path).unwrap(),
        ),
        Arc::new(ResourceRegistry::from_file(&resource_path).unwrap()),
        Arc::new(BatchBackend),
        24495,
    );
    let store = Arc::new(TaskStore::new(":memory:").unwrap());
    let task = store.create("Simple").await.unwrap();
    // This is a complete legacy request+approval pair: the former helper
    // would authorize it before asking the model, and fail at missing MCP.
    record_tool_request(&store, task.id, &call()).await.unwrap();
    // Legacy history must never grant authority to a provider-id reuse.
    store
        .append_context(
            task.id,
            ContextEntry {
                role: TOOL_APPROVAL_ROLE.to_owned(),
                content: "old human approval".to_owned(),
                at: Utc::now(),
                tool_call_id: Some(call().id),
            },
        )
        .await
        .unwrap();
    let mut messages = vec![Message::new(Role::User, "test")];
    let session = scheduler.begin_session("Simple", false).await.unwrap();
    let err = agent_steps(
        &store,
        &session,
        task.id,
        &mut messages,
        &[],
        None,
        &[],
        "fixture-server",
        None,
    )
    .await
    .err()
    .expect("batch must be rejected");
    assert!(
        err.to_string().contains("ровно один вызов"),
        "batch validation must precede MCP lookup and legacy approval: {err:#}"
    );
    assert_eq!(messages.len(), 1, "no assistant calls are published");
    let task = store.get(task.id).await.unwrap().unwrap();
    assert_eq!(task.status, TaskStatus::Running);
    assert!(task.pending_tool_approval.is_none());
    assert_eq!(
        task.context.len(),
        2,
        "no batch request/result is persisted"
    );
    assert_eq!(task.context[0].role, TOOL_REQUEST_ROLE);
    assert_eq!(task.context[1].role, TOOL_APPROVAL_ROLE);
}

#[tokio::test]
async fn changed_command_or_arguments_are_rejected_before_mcp_connection() {
    let store = TaskStore::new(":memory:").unwrap();
    let approval = parked(&store).await;
    let config = McpServerConfig {
        command: approval.server.command.clone(),
        args: approval.server.args.clone(),
        auto_approve: Vec::new(),
        deadlines: Default::default(),
    };
    assert!(validate_approval_config(&approval, Some(&config)).is_ok());
    assert!(validate_approval_config(&approval, None).is_err());
    let mut changed = config.clone();
    changed.command.push_str("-replacement");
    assert!(validate_approval_config(&approval, Some(&changed)).is_err());
    let mut changed = config.clone();
    changed.args.reverse();
    assert!(validate_approval_config(&approval, Some(&changed)).is_err());
    let mut changed = config;
    changed.args.push("--changed-config".to_owned());
    assert!(validate_approval_config(&approval, Some(&changed)).is_err());
}

#[tokio::test]
async fn immediate_continue_after_pause_rejects_without_appending_or_restarting() {
    let dir = FixtureDirectory::new();
    let resource_path = dir.0.join("resources.yaml");
    std::fs::write(
        &resource_path,
        "Fake:\n  vram_mb: 1000\n  load_seconds: 1\n",
    )
    .unwrap();
    let capabilities_path = dir.0.join("capabilities.yaml");
    std::fs::write(&capabilities_path, "Simple:\n  primary: Fake\n").unwrap();
    let resource_registry = Arc::new(ResourceRegistry::from_file(&resource_path).unwrap());
    let state = AppState {
        task_store: Arc::new(TaskStore::new(":memory:").unwrap()),
        scheduler: Arc::new(Scheduler::new(
            Arc::new(
                crate::capability_registry::CapabilityRegistry::from_file(&capabilities_path)
                    .unwrap(),
            ),
            resource_registry.clone(),
            Arc::new(BatchBackend),
            24495,
        )),
        resource_registry,
        control: TaskControl::default(),
    };
    let task = state.task_store.create("Simple").await.unwrap();
    // A live registered receiver represents a worker that has not yet dropped
    // its execution slot. No sleeps or real model generation are needed.
    let receiver = state.control.register(task.id).await.unwrap();
    assert_eq!(
        pause_task(State(state.clone()), Path(task.id))
            .await
            .ok()
            .expect("pause accepts registered worker"),
        StatusCode::OK
    );
    assert!(
        *receiver.borrow(),
        "pause must signal the still-registered worker"
    );
    let before = state.task_store.get(task.id).await.unwrap().unwrap();
    assert_eq!(before.status, TaskStatus::Paused);
    let before_context = serde_json::to_value(&before.context).unwrap();
    let response = continue_task(
        State(state.clone()),
        Path(task.id),
        Json(ContinueRequest {
            message: Some("must not be appended".to_owned()),
            allow_manual: Some(false),
        }),
    )
    .await
    .err()
    .expect("paused worker still exiting requires a conflict")
    .into_response();
    assert_eq!(response.status(), StatusCode::CONFLICT);
    let after = state.task_store.get(task.id).await.unwrap().unwrap();
    assert_eq!(after.status, TaskStatus::Paused);
    assert_eq!(
        serde_json::to_value(&after.context).unwrap(),
        before_context
    );
    assert!(
        *receiver.borrow(),
        "cancel signal must not be replaced by fresh receiver"
    );
    assert_eq!(state.control.running.lock().await.len(), 1);
    assert!(state.scheduler.snapshot().await.is_empty());
    state.control.unregister(task.id).await;
}

struct SingleToolBackend(std::sync::atomic::AtomicUsize);

#[async_trait::async_trait]
impl crate::model_backend::ModelBackend for SingleToolBackend {
    async fn is_loaded(&self, _: &str) -> anyhow::Result<bool> {
        Ok(false)
    }
    async fn load(&self, _: &str) -> anyhow::Result<()> {
        Ok(())
    }
    async fn unload(&self, _: &str) -> anyhow::Result<()> {
        Ok(())
    }
    async fn generate(&self, _: &str, _: GenerateRequest) -> anyhow::Result<GenerateResponse> {
        if self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst) == 0 {
            Ok(GenerateResponse::ToolCalls(vec![call()]))
        } else {
            Ok(GenerateResponse::Text("fixture completed".to_owned()))
        }
    }
}

/// This deliberately uses the real rmcp stdio transport and McpClient, not
/// a mock of execute_tool. Run the test binary directly with a /tmp workdir:
/// execute_tool's existing audit path is relative to the process directory.
#[tokio::test]
#[ignore = "requires python3 and an isolated /tmp working directory for the audit log"]
async fn local_stdio_dispatch_executes_only_the_exact_once_approved_invocation() {
    assert!(
        std::env::current_dir()
            .unwrap()
            .starts_with(std::env::temp_dir()),
        "run this ignored test binary from an isolated temporary directory"
    );
    let dir = FixtureDirectory::new();
    let script_path = dir.0.join("synthetic_mcp.py");
    let dispatch_path = dir.0.join("dispatch.jsonl");
    let other_dispatch_path = dir.0.join("other-dispatch.jsonl");
    // Entirely synthetic, locally authored fixture: no imports beyond the
    // Python standard library, networking, external packages or model calls.
    std::fs::write(
        &script_path,
        r#"import json
import sys

for raw in sys.stdin:
    request = json.loads(raw)
    if "id" not in request:
        continue
    method = request["method"]
    if method == "initialize":
        result = {"protocolVersion": request["params"]["protocolVersion"],
                  "capabilities": {"tools": {}},
                  "serverInfo": {"name": sys.argv[2], "version": "1.0"}}
    elif method == "tools/list":
        result = {"tools": [{"name": "execute_blender_code",
                             "description": "synthetic tool without external effects",
                             "inputSchema": {"type": "object"}}]}
    elif method == "tools/call":
        with open(sys.argv[1], "a", encoding="utf-8") as journal:
            journal.write(json.dumps(request["params"]) + "\n")
        result = {"content": [{"type": "text", "text": "fixture-result"}]}
    elif method == "ping":
        result = {}
    else:
        print(json.dumps({"jsonrpc": "2.0", "id": request["id"],
                          "error": {"code": -32601, "message": "unknown method"}}), flush=True)
        continue
    print(json.dumps({"jsonrpc": "2.0", "id": request["id"], "result": result}), flush=True)
"#,
    )
    .unwrap();
    let config = McpServerConfig {
        command: "python3".to_owned(),
        args: vec![
            script_path.to_string_lossy().into_owned(),
            dispatch_path.to_string_lossy().into_owned(),
            "fixture-approved-peer".to_owned(),
        ],
        auto_approve: Vec::new(),
        deadlines: Default::default(),
    };
    let timeout = std::time::Duration::from_secs(5);
    let client = tokio::time::timeout(timeout, McpClient::connect(&config))
        .await
        .expect("synthetic MCP handshake must finish")
        .unwrap();
    let tools = tokio::time::timeout(timeout, client.list_tools())
        .await
        .unwrap()
        .unwrap();
    assert_eq!(tools.len(), 1);
    assert_eq!(tools[0].name, call().name);

    let resource_path = dir.0.join("resources.yaml");
    std::fs::write(
        &resource_path,
        "Fake:\n  vram_mb: 1000\n  load_seconds: 1\n",
    )
    .unwrap();
    let capabilities_path = dir.0.join("capabilities.yaml");
    std::fs::write(&capabilities_path, "Simple:\n  primary: Fake\n").unwrap();
    let backend = Arc::new(SingleToolBackend(std::sync::atomic::AtomicUsize::new(0)));
    let scheduler = Scheduler::new(
        Arc::new(
            crate::capability_registry::CapabilityRegistry::from_file(&capabilities_path).unwrap(),
        ),
        Arc::new(ResourceRegistry::from_file(&resource_path).unwrap()),
        backend.clone(),
        24495,
    );
    let store = Arc::new(TaskStore::new(":memory:").unwrap());
    let task = store.create("Simple").await.unwrap();
    let session = scheduler.begin_session("Simple", false).await.unwrap();
    let mut messages = vec![Message::new(Role::User, "synthetic request")];
    let parked_outcome = tokio::time::timeout(
        timeout,
        agent_steps(
            &store,
            &session,
            task.id,
            &mut messages,
            &tools,
            Some(&client),
            &[],
            client.server_name(),
            None,
        ),
    )
    .await
    .unwrap()
    .unwrap();
    assert!(matches!(parked_outcome, LoopOutcome::AwaitingHuman));
    assert!(
        !dispatch_path.exists(),
        "pending approval must not dispatch"
    );
    let pending = store
        .get(task.id)
        .await
        .unwrap()
        .unwrap()
        .pending_tool_approval
        .unwrap();
    assert_eq!(pending.tool_name, call().name);
    assert_eq!(pending.arguments, call().arguments);
    assert_eq!(&pending.server, client.identity());
    // A mutable last request must never become the approved target.
    let mut malicious = call();
    malicious.id = "last-forged".to_owned();
    malicious.name = "different_tool".to_owned();
    malicious.arguments = "{\"dangerous\":true}".to_owned();
    record_tool_request(&store, task.id, &malicious)
        .await
        .unwrap();
    let claimed = store
        .claim_tool_approval(task.id, pending.request_id, true)
        .await
        .unwrap()
        .unwrap();
    assert!(store
        .claim_tool_approval(task.id, pending.request_id, true)
        .await
        .unwrap()
        .is_none());

    // A real second connected client has a different peer/config identity.
    // Reject it before the execution claim, leaving the valid target usable.
    let mut other_config = config.clone();
    other_config.args[1] = other_dispatch_path.to_string_lossy().into_owned();
    other_config.args[2] = "fixture-replacement-peer".to_owned();
    let other_client = tokio::time::timeout(timeout, McpClient::connect(&other_config))
        .await
        .unwrap()
        .unwrap();
    let mismatch = tokio::time::timeout(
        timeout,
        agent_steps(
            &store,
            &session,
            task.id,
            &mut messages,
            &tools,
            Some(&other_client),
            &[],
            other_client.server_name(),
            Some(claimed.clone()),
        ),
    )
    .await
    .unwrap();
    assert!(mismatch.is_err());
    assert!(!dispatch_path.exists());
    assert!(!other_dispatch_path.exists());
    tokio::time::timeout(timeout, other_client.shutdown())
        .await
        .unwrap()
        .unwrap();

    let completed = tokio::time::timeout(
        timeout,
        agent_steps(
            &store,
            &session,
            task.id,
            &mut messages,
            &tools,
            Some(&client),
            &[],
            client.server_name(),
            Some(claimed.clone()),
        ),
    )
    .await
    .unwrap()
    .unwrap();
    assert!(matches!(completed, LoopOutcome::Answer(_)));
    let journal = std::fs::read_to_string(&dispatch_path).unwrap();
    let dispatches: Vec<serde_json::Value> = journal
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    assert_eq!(dispatches.len(), 1);
    assert_eq!(dispatches[0]["name"], call().name);
    assert_eq!(
        dispatches[0]["arguments"],
        serde_json::from_str::<serde_json::Value>(&call().arguments).unwrap()
    );
    let saved = store.get(task.id).await.unwrap().unwrap();
    let results: Vec<_> = saved
        .context
        .iter()
        .filter(|entry| entry.role == TOOL_ROLE)
        .collect();
    assert_eq!(results.len(), 1);
    assert_eq!(results[0].tool_call_id.as_deref(), Some(call().id.as_str()));
    assert_eq!(results[0].content, "fixture-result");

    let replay = tokio::time::timeout(
        timeout,
        agent_steps(
            &store,
            &session,
            task.id,
            &mut messages,
            &tools,
            Some(&client),
            &[],
            client.server_name(),
            Some(claimed),
        ),
    )
    .await
    .unwrap();
    assert!(replay.is_err());
    assert_eq!(std::fs::read_to_string(&dispatch_path).unwrap(), journal);
    assert_eq!(backend.0.load(std::sync::atomic::Ordering::SeqCst), 2);

    // Cancellation wins before the actual dispatch boundary, even though
    // the decision had already been successfully claimed.
    let cancelled_task = store.create("Simple").await.unwrap();
    let cancelled = store
        .park_tool_approval(
            cancelled_task.id,
            Uuid::new_v4(),
            &call(),
            client.identity().clone(),
        )
        .await
        .unwrap()
        .unwrap();
    store
        .claim_tool_approval(cancelled_task.id, cancelled.request_id, true)
        .await
        .unwrap()
        .unwrap();
    store
        .set_status(cancelled_task.id, TaskStatus::Cancelled)
        .await
        .unwrap();
    let cancellation = tokio::time::timeout(
        timeout,
        agent_steps(
            &store,
            &session,
            cancelled_task.id,
            &mut Vec::new(),
            &tools,
            Some(&client),
            &[],
            client.server_name(),
            Some(cancelled),
        ),
    )
    .await
    .unwrap();
    assert!(cancellation.is_err());
    assert_eq!(std::fs::read_to_string(&dispatch_path).unwrap(), journal);
    assert!(!other_dispatch_path.exists());
    assert_eq!(backend.0.load(std::sync::atomic::Ordering::SeqCst), 2);
    tokio::time::timeout(timeout, client.shutdown())
        .await
        .unwrap()
        .unwrap();
}
